package com.ecommerce.backend.service;

import com.ecommerce.backend.exception.*;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class AdminOperationsService {
 private final JdbcTemplate jdbc;
 public List<Map<String,Object>> rows(String sql,Object...args){return jdbc.query(sql,(rs,n)->{Map<String,Object> row=new LinkedHashMap<>();var meta=rs.getMetaData();for(int i=1;i<=meta.getColumnCount();i++){Object value=rs.getObject(i);if(value instanceof java.sql.Timestamp)value=rs.getObject(i,OffsetDateTime.class);if(value instanceof UUID)value=value.toString();row.put(meta.getColumnLabel(i).toLowerCase(Locale.ROOT),value);}return row;},args);}
 public Map<String,Object> page(String select,String from,String filter,int page,Object...args){var values=new ArrayList<>(Arrays.asList(args));Long total=jdbc.queryForObject("SELECT count(*) "+from+filter,Long.class,args);values.add(20);values.add(page*20);return Map.of("items",rows(select+" "+from+filter+" ORDER BY created_at DESC,1 LIMIT ? OFFSET ?",values.toArray()),"total",total,"page",page);}
 public List<Map<String,Object>> require(String sql,Object...args){var result=rows(sql,args);if(result.isEmpty())throw new ResourceNotFoundException("Registro no encontrado");return result;}
 @Transactional public void audit(UUID actor,String module,String target,String action,String reason){jdbc.update("INSERT INTO rya.historial_administrativo(id,actor_id,modulo,registro,accion,motivo) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),actor,module,target,action,reason);}
 public Map<String,Object> orders(String search,String status,int page){return page("SELECT p.id,p.codigo,p.nombre_completo,p.estado,p.monto_total,p.created_at,p.estado_entrega","FROM rya.pedidos p ","WHERE p.is_deleted=false AND (LOWER(p.codigo) LIKE ? OR LOWER(p.nombre_completo) LIKE ?) AND (?='' OR p.estado=?)",page,"%"+search.toLowerCase(Locale.ROOT)+"%","%"+search.toLowerCase(Locale.ROOT)+"%",status,status);}
 public Map<String,Object> order(UUID id){var header=require("SELECT id,codigo,estado,nombre_completo,email,telefono,created_at,subtotal,envio,monto_total,direccion_envio,referencia_envio,entrega_snapshot,estado_entrega,transportista_seguimiento,codigo_seguimiento FROM rya.pedidos WHERE id=? AND is_deleted=false",id).getFirst();return Map.of("pedido",header,"productos",rows("SELECT descripcion_snapshot,sku_snapshot,cantidad,precio_unitario,subtotal FROM rya.detalle_pedido WHERE pedido_id=? AND is_deleted=false",id),"pagos",rows("SELECT estado,status_detail,monto,moneda,mp_order_id,created_at FROM rya.pagos WHERE pedido_id=? ORDER BY created_at DESC",id),"historial",rows("SELECT accion,motivo,created_at FROM rya.historial_administrativo WHERE modulo='pedidos' AND registro=? ORDER BY created_at DESC",id.toString()));}
 @Transactional public void cancel(UUID id,String reason,UUID actor){var order=require("SELECT estado FROM rya.pedidos WHERE id=? AND is_deleted=false FOR UPDATE",id).getFirst();if(!List.of("PENDIENTE","PENDIENTE_PAGO").contains(order.get("estado")))throw new BadRequestException("Solo se pueden cancelar pedidos pendientes sin cobros iniciados.");if(jdbc.queryForObject("SELECT count(*) FROM rya.pagos WHERE pedido_id=?",Long.class,id)>0)throw new BadRequestException("Este pedido tiene intentos de pago. Primero debe reconciliarse con Mercado Pago; no se cancelará desde este botón.");jdbc.update("UPDATE rya.pedidos SET estado='CANCELADO',updated_at=CURRENT_TIMESTAMP WHERE id=?",id);audit(actor,"pedidos",id.toString(),"CANCELADO",reason);}
 public Map<String,Object> reviews(String status,int page){return page("SELECT r.id,p.nombre AS producto,u.nombre AS autor,r.calificacion,r.comentario,r.estado_moderacion,r.motivo_moderacion,r.revision_admin,r.created_at","FROM rya.resenas_producto r JOIN rya.productos p ON p.id=r.producto_id JOIN rya.usuarios u ON u.id=r.usuario_id ","WHERE r.is_deleted=false AND (?='' OR r.estado_moderacion=?)",page,status,status);}
 @Transactional public void moderate(UUID id,String state,String reason,long version,UUID actor){int updated=jdbc.update("UPDATE rya.resenas_producto SET publicada=?,estado_moderacion=?,motivo_moderacion=?,moderado_por=?,moderado_at=CURRENT_TIMESTAMP,revision_admin=revision_admin+1 WHERE id=? AND is_deleted=false AND revision_admin=?","APROBADA".equals(state),state,reason,actor,id,version);if(updated!=1)throw new ConflictException("La reseña cambió o no está disponible. Actualiza el listado.");audit(actor,"resenas",id.toString(),state,reason);}
 public Map<String,Object> cases(int page){return page("SELECT s.id,s.pedido_id,p.codigo,s.tipo,s.motivo,s.evidencia_url,s.estado,s.resolucion,s.version,s.created_at","FROM rya.solicitudes_postventa s JOIN rya.pedidos p ON p.id=s.pedido_id ","WHERE p.is_deleted=false",page);}
 @Transactional public UUID createCase(String code,String type,String reason,String evidence,UUID actor){var order=require("SELECT id,estado FROM rya.pedidos WHERE codigo=? AND is_deleted=false FOR UPDATE",code).getFirst();if(!"PAGADO".equals(order.get("estado")))throw new BadRequestException("La postventa requiere una compra con pago confirmado.");safeUrl(evidence);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO rya.solicitudes_postventa(id,pedido_id,tipo,motivo,evidencia_url,creado_por) VALUES (?,?,?,?,?,?)",id,UUID.fromString(order.get("id").toString()),type,reason,evidence,actor);audit(actor,"postventa",id.toString(),"ABIERTA",reason);return id;}
 @Transactional public void resolve(UUID id,String state,String resolution,long version,UUID actor){var current=require("SELECT estado FROM rya.solicitudes_postventa WHERE id=? FOR UPDATE",id).getFirst();var previous=current.get("estado");boolean valid=("ABIERTA".equals(previous)&&"EN_REVISION".equals(state))||("EN_REVISION".equals(previous)&&List.of("APROBADA","RECHAZADA").contains(state))||(List.of("APROBADA","RECHAZADA").contains(previous)&&"CERRADA".equals(state));if(!valid)throw new BadRequestException("Avanza de abierta a revisión, después a aprobada o rechazada, y finalmente a cerrada.");if(jdbc.update("UPDATE rya.solicitudes_postventa SET estado=?,resolucion=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND version=?",state,resolution,id,version)!=1)throw new ConflictException("La solicitud cambió. Actualiza el listado.");audit(actor,"postventa",id.toString(),state,resolution);}
 public static void safeUrl(String value){if(value==null||value.isBlank())return;try{var uri=java.net.URI.create(value);if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw new BadRequestException("Usa una URL HTTPS válida.");}}
 public Map<String,Object> reports(LocalDate start,LocalDate end){if(end.isBefore(start)||java.time.temporal.ChronoUnit.DAYS.between(start,end)>366)throw new BadRequestException("El periodo debe tener entre 1 y 367 días.");var zone=ZoneId.of("America/Lima");var from=start.atStartOfDay(zone).toOffsetDateTime();var to=end.plusDays(1).atStartOfDay(zone).toOffsetDateTime();Map<String,BigDecimal> daily=new TreeMap<>();jdbc.query("SELECT created_at,monto_total FROM rya.pedidos WHERE estado='PAGADO' AND is_deleted=false AND created_at>=? AND created_at<?",(org.springframework.jdbc.core.RowCallbackHandler)rs->{String day=rs.getObject(1,OffsetDateTime.class).atZoneSameInstant(zone).toLocalDate().toString();daily.merge(day,rs.getBigDecimal(2),BigDecimal::add);},from,to);var sales=daily.entrySet().stream().map(e->Map.of("fecha",e.getKey(),"total",e.getValue())).toList();var top=rows("SELECT d.sku_snapshot AS sku,d.descripcion_snapshot AS producto,SUM(d.cantidad) AS unidades,SUM(d.subtotal) AS importe FROM rya.detalle_pedido d JOIN rya.pedidos p ON p.id=d.pedido_id WHERE p.estado='PAGADO' AND p.is_deleted=false AND d.is_deleted=false AND p.created_at>=? AND p.created_at<? GROUP BY d.sku_snapshot,d.descripcion_snapshot ORDER BY unidades DESC LIMIT 20",from,to);var low=rows("SELECT p.id,p.sku,p.nombre,COALESCE(SUM(e.cantidad-e.reservado),0) AS disponible FROM rya.productos p LEFT JOIN rya.existencias e ON e.producto_id=p.id AND e.is_deleted=false WHERE p.is_deleted=false GROUP BY p.id,p.sku,p.nombre HAVING COALESCE(SUM(e.cantidad-e.reservado),0)<=3 ORDER BY disponible,p.sku LIMIT 100");return Map.of("ventas",sales,"totalVentas",daily.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add),"masVendidos",top,"stockBajo",low,"pedidosPendientes",jdbc.queryForObject("SELECT count(*) FROM rya.pedidos WHERE is_deleted=false AND estado IN ('PENDIENTE','PENDIENTE_PAGO')",Long.class),"desde",start,"hasta",end);}
}
